let lang='en';
try { lang=localStorage.getItem('encompass-language')||'en'; } catch {}
if (!copy[lang]) lang='en';
const text = key => copy[lang][key] || copy.en[key] || '';
function translate(value){lang=value;document.documentElement.lang=value==='zh'?'zh':value;all('[data-t]').forEach(el=>el.innerHTML=text(el.dataset.t));$('#flag').textContent={en:'🇬🇧',fr:'🇫🇷',zh:'🇨🇳'}[lang];$('#language').value=lang;$('#sign-in').setAttribute('aria-label',text('signin'));$('#form-status').textContent='';try{localStorage.setItem('encompass-language',lang)}catch{};document.title=`Encompass Corp. — ${text(isMarketing?'marketing':'data')}`;all('.page-nav a').forEach((a,i)=>a.setAttribute('aria-label',text(['home','about','solutions','ourTeam','contact'][i])));}
translate(lang);
$('#language').addEventListener('change',e=>translate(e.target.value));
const scenes=all('.scene'), dots=all('.page-nav a');
let ticking=false;
const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)');
const tones = [[8,11,14],[240,241,240],[8,11,14],[231,235,237],[8,10,12]];
const clamp = v => Math.max(0, Math.min(1,v));
const ease = v => {v=clamp(v); return v*v*(3-2*v)};
function updateScroll(){
 const y=window.scrollY, h=window.innerHeight;
 if(isMarketing){ const edge=$('.hero-frame').offsetHeight; $('.division').style.top=`${Math.max(20,edge-88-y)}px`; ticking=false; return; }
 const start=scenes[0].offsetHeight-91;
 $('.division').style.top=`${Math.max(window.innerWidth<641?20:24,start-y)}px`;
 let current=0, background=tones[0];
 scenes.forEach((scene,i)=>{
  const rect=scene.getBoundingClientRect();
  if(rect.top<h*.48)current=i;
  if(i && rect.top<h){
   const progress=reducedMotion.matches ? +(rect.top<h*.5) : ease(1-rect.top/h);
   background=tones[i-1].map((c,j)=>Math.round(c+(tones[i][j]-c)*progress));
  }
  const exposure=clamp(Math.min((h-rect.top)/h,rect.bottom/h));
  scene.style.opacity=reducedMotion.matches?'1':String(ease(exposure));
 });
 document.body.style.backgroundColor=`rgb(${background.join(',')})`;
 const heroProgress=clamp(y/scenes[0].offsetHeight);
 $('.site-visual').style.opacity=String(1-ease(clamp(heroProgress*1.7)));
 $('.site-visual').style.visibility=heroProgress>=1?'hidden':'visible';
 dots.forEach((a,i)=>{a.classList.toggle('active',i===current);if(i===current)a.setAttribute('aria-current','true');else a.removeAttribute('aria-current')});
 document.body.classList.toggle('on-light',scenes[current].dataset.tone==='light');
 ticking=false;
}
window.addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(updateScroll);ticking=true;}},{passive:true});window.addEventListener('resize',updateScroll);updateScroll();
const menu=$('#menu-dialog'), info=$('#info-dialog');
$('#menu-open').onclick=()=>menu.showModal();
all('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());
all('dialog').forEach(d=>d.addEventListener('click',e=>{const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}));
all('#menu-dialog a').forEach(a=>a.onclick=()=>menu.close());
function openInfo(title,body,kicker='ENCOMPASS CORP.'){ $('#dialog-title').textContent=title;$('#dialog-text').textContent=body;$('#dialog-kicker').textContent=kicker;$('#dialog-extra').replaceChildren();$('#dialog-contact').hidden=false;$('#dialog-contact').style.display='flex';info.showModal();}
$('#sign-in').onclick=()=>{productIndex=0;openInfo(text('signinTitle'),text('signinText'));};
$('#marketing').onclick=()=>{if(isMarketing) $('#home').scrollIntoView({behavior:reducedMotion.matches?'instant':'smooth'}); else location.href='marketing.html';};
$('#data-division').onclick=()=>{if(isMarketing) location.href='index.html'; else $('#products').scrollIntoView({behavior:reducedMotion.matches?'instant':'smooth'});};
let productIndex=0;
all('[data-product]').forEach(b=>b.onclick=()=>{productIndex=Number(b.dataset.product)+1;openInfo(text(['law','crm','flow'][productIndex-1]),text(['lawDesc','crmDesc','flowDesc'][productIndex-1])+' '+text('solutionText'),text('development'));});
$('#dialog-contact').onclick=()=>{info.close();$('#interest').selectedIndex=productIndex;productIndex=0;$('#contact').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});};
$('#credits').onclick=()=>{openInfo(text('creditsTitle'),text('creditsText'));$('#dialog-contact').style.display='none';const links=isMarketing ? [['RDNE Stock project — Business team','https://www.pexels.com/photo/people-in-a-business-meeting-7888760/'],['Business analysis','https://www.pexels.com/photo/using-laptop-in-a-business-meeting-7693683/'],['Social media work','https://www.pexels.com/photo/person-using-laptop-and-smartphone-4549413/'],['Website development','https://www.pexels.com/photo/crop-faceless-developer-working-on-software-code-on-laptop-5926382/'],['Pexels License','https://www.pexels.com/license/']] : [['Danist Soh — Architecture','https://unsplash.com/photos/clear-glass-and-black-building-kWvsIYwUkJs'],['Max Bürgi — Light study','https://unsplash.com/photos/abstract-light-streaks-on-a-blue-background-2pPNznUrp70'],['Unsplash License','https://unsplash.com/license']];links.forEach(([label,url])=>{let a=document.createElement('a');a.textContent=label+' ↗';a.href=url;a.target='_blank';a.rel='noopener noreferrer';$('#dialog-extra').append(a)})};
$('#contact-form').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.currentTarget);const subject=`Encompass enquiry — ${d.get('interest')}`;const body=`Name: ${d.get('name')}\nEmail: ${d.get('email')}\nInterest: ${d.get('interest')}\n\n${d.get('message')}`;location.href=`mailto:santiagomatooane3@gmail.com?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;$('#form-status').textContent=text('prepared');});
